        ast.GtE: operator.ge,
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
        ast.Not: operator.not_,
    }

    # Allowed field names
    fields = {'id', 'name', 'email'}

    def evaluate(node):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in fields:
                return node.id
            raise ValueError(f"Unknown field: {node.id}")
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = evaluate(comparator)
                op_type = type(op)
                if op_type not in operators:
                    raise ValueError(f"Unsupported operator: {op_type}")
                return operators[op_type](left, right)
        elif isinstance(node, ast.BoolOp):
            values = [evaluate(v) for v in node.values]
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Unsupported operator: {op_type}")
            # This is tricky because we don't have the user object yet.
            # Maybe we should return a lambda or a structure.
            return (op_type, values)
        elif isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, ast.Not):
                raise ValueError(f"Unsupported unary operator: {type(node.op)}")
            return (ast.Not, evaluate(node.operand))
        else:
            raise ValueError(f"Unsupported node type: {type(node)}")

    try:
        tree = ast.parse(expr, mode='eval')
        return evaluate(tree.body)
    except Exception as e:
        print(f"Error: {e}")
        return None

