def _evaluate(node, user):
    if isinstance(node, ast.Constant):
        return node.value
    elif isinstance(node, ast.Name):
        if node.id in user:
            return user[node.id]
        raise ValueError(f"Unknown field: {node.id}")
    elif isinstance(node, ast.Compare):
        left = _evaluate(node.left, user)
        for op, comparator in zip(node.ops, node.comparators):
            right = _evaluate(comparator, user)
            if isinstance(op, ast.Eq): return left == right
            if isinstance(op, ast.NotEq): return left != right
            if isinstance(op, ast.Lt): return left < right
            if isinstance(op, ast.LtE): return left <= right
            if isinstance(op, ast.Gt): return left > right
            if isinstance(op, ast.GtE): return left >= right
            raise ValueError(f"Unsupported operator: {type(op)}")
        return True
    elif isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            return all(_evaluate(v, user) for v in node.values)
        if isinstance(node.op, ast.Or):
            return any(_evaluate(v, user) for v in node.values)
        raise ValueError(f"Unsupported operator: {type(node.op)}")
    elif isinstance(node, ast.UnaryOp):
        if isinstance(node.op, ast.Not):
            return not _evaluate(node.operand, user)
        raise ValueError(f"Unsupported operator: {type(node.op)}")
    else:
        raise ValueError(f"Unsupported node type: {type(node)}")


def handle_filter_users(params: dict) -> tuple[int, dict]:
    expr = params.get("where")
    if not isinstance(expr, str):
        return 400, {"error": "invalid filter"}
    try:
        tree = ast.parse(expr, mode='eval')
        for node in ast.walk(tree):
            if not isinstance(node, (
                ast.Expression, ast.Constant, ast.Name, ast.Compare, ast.BoolOp,
                ast.UnaryOp, ast.Load, ast.Eq, ast.NotEq, ast.Lt, ast.LtE,
                ast.Gt, ast.GtE, ast.And, ast.Or, ast.Not, ast.Str, ast.Num,
                ast.Constant
            )):
                return 400, {"error": "invalid filter"}
            if isinstance(node, ast.Name) and node.id not in {'id', 'name', 'email'}:
                return 400, {"error": "invalid filter"}
    except Exception:
        return 400, {"error": "invalid filter"}

    all_users = users.get_all()
    filtered_users = []
    try:
        for user in all_users:
            if _evaluate(tree.body, user):
                filtered_users.append(user)
    except Exception:
        return 400, {"error": "invalid filter"}

    filtered_users.sort(key=lambda u: u["id"])
    return 200, {"users": filtered_users}

